import { useState } from "react";
import { useNavigate } from "react-router-dom";

const gradientText = {
  background: "linear-gradient(135deg, rgb(148, 0, 211), rgb(237, 128, 233))",
  WebkitBackgroundClip: "text",
  WebkitTextFillColor: "transparent",
  backgroundClip: "text",
};

const inputStyle = (focus) => ({
  width: "100%",
  height: "48px",
  padding: "0 14px",
  border: `1.5px solid ${focus ? "rgb(148, 0, 211)" : "#e0c8f8"}`,
  borderRadius: "8px",
  outline: "none",
  background: focus ? "#f5eaff" : "#fdf8ff",
  marginBottom: "14px",
  fontSize: "14px",
});

export default function Login() {
  const navigate = useNavigate();

  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [focusId, setFocusId] = useState(false);
  const [focusPw, setFocusPw] = useState(false);

  const handleLogin = () => {
    setError("");
    if (!identifier.trim()) { setError("Email or Phone is required"); return; }
    if (!password.trim()) { setError("Password is required"); return; }
    setLoading(true);
    setTimeout(() => { setLoading(false); navigate("/home"); }, 1000);
  };

  return (
    <div className="main-container">

      {/* LEFT PANEL */}
      <div className="login-left">
        <h2 className="logo">TheZuro</h2>
        <p className="tagline">Join India's fastest growing shopping platform 🚀</p>
      </div>

      {/* RIGHT PANEL */}
      <div className="login-right">
        <div className="form-container">

          <h1 className="brand-title">TheZuro</h1>
          <h2 className="welcome-text">Welcome Back 👋</h2>

          {error && <div className="error">{error}</div>}

          <input
            style={inputStyle(focusId)}
            placeholder="Email or Phone"
            value={identifier}
            onChange={(e) => setIdentifier(e.target.value)}
            onFocus={() => setFocusId(true)}
            onBlur={() => setFocusId(false)}
          />

          <div className="password-box">
            <input
              style={inputStyle(focusPw)}
              type={showPw ? "text" : "password"}
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              onFocus={() => setFocusPw(true)}
              onBlur={() => setFocusPw(false)}
            />
            <span onClick={() => setShowPw(!showPw)}>👁</span>
          </div>

          {/* ✅ FORGOT PASSWORD */}
          <div className="forgot">
            <span onClick={() => navigate("/forgot-password")}>Forgot Password?</span>
          </div>

          <button onClick={handleLogin}>
            {loading ? "Loading..." : "Login"}
          </button>

        </div>
      </div>

      <style>{`
        * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'DM Sans', Arial, sans-serif; }
        html, body { width: 100%; height: 100%; overflow-x: hidden; }

        .main-container { display: flex; flex-direction: column; min-height: 100dvh; }
        .login-left { display: none; }

        .login-right {
          width: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 250px 20px 20px;
        }

        .form-container {
          width: 100%;
          max-width: 380px;
          text-align: center;
          margin-top: 40px;
        }

        .brand-title {
          font-size: 28px;
          font-weight: 700;
          background: linear-gradient(135deg, rgb(148, 0, 211), rgb(237, 128, 233));
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          background-clip: text;
          margin-bottom: 6px;
        }

        .welcome-text {
          font-size: 20px;
          font-weight: 600;
          background: linear-gradient(135deg, rgb(148, 0, 211), rgb(237, 128, 233));
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          background-clip: text;
          margin-bottom: 24px;
        }

        .error { color: red; margin-bottom: 10px; font-size: 13px; text-align: left; }

        .password-box { position: relative; }
        .password-box span { position: absolute; right: 12px; top: 13px; cursor: pointer; }

        /* ✅ FORGOT PASSWORD */
        .forgot {
          text-align: right;
          margin-top: -6px;
          margin-bottom: 18px;
        }
        .forgot span {
          font-size: 13px;
          font-weight: 500;
          background: linear-gradient(135deg, rgb(148, 0, 211), rgb(237, 128, 233));
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          background-clip: text;
          cursor: pointer;
        }

        button {
          width: 100%;
          height: 48px;
          background: linear-gradient(135deg, rgb(148, 0, 211), rgb(237, 128, 233));
          color: white;
          border: none;
          border-radius: 8px;
          cursor: pointer;
          font-size: 15px;
          font-weight: 600;
          box-shadow: 0 4px 18px rgba(148,0,211,0.3);
        }

        @media (min-width: 768px) {
          .main-container { flex-direction: row; }
          .login-left {
            display: flex;
            flex: 1;
            background: linear-gradient(135deg, rgb(148, 0, 211), rgb(237, 128, 233));
            color: white;
            padding: 60px;
            flex-direction: column;
            justify-content: center;
          }
          .logo { font-size: 32px; font-weight: 700; margin-bottom: 12px; }
          .tagline { font-size: 16px; opacity: 0.85; }
          .login-right { max-width: 500px; }
        }
      `}</style>
    </div>
  );
}
